SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '30s';

CREATE TABLE IF NOT EXISTS substitution (
  "id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  "game_id" uuid NOT NULL REFERENCES game(id) ON DELETE CASCADE,
  "player_off_id" uuid NOT NULL REFERENCES player(id) ON DELETE CASCADE,
  "player_on_id" uuid NOT NULL REFERENCES player(id) ON DELETE CASCADE,
  "side" text NOT NULL CHECK (side IN ('home', 'away')),
  "minute" integer NOT NULL CHECK (minute >= 0 AND minute <= 130),
  "added_time" integer CHECK (added_time >= 0),
  "period" text,
  "source_order" integer CHECK (source_order >= 0),
  "txid" BIGINT DEFAULT pg_current_xact_id()::text::bigint,
  CHECK (player_off_id <> player_on_id)
);

